doc.core_properties.title = "Онтологии в анализе социальных данных с помощью ИИ"
doc.core_properties.subject = "Раздел учебника Инструменты ИИ для социального архитектора"
doc.core_properties.author = ""
doc.core_properties.keywords = "онтология, анализ текстов, экспертная разметка, валидация"
doc.core_properties.comments = ""
