def p(text):
    return doc.add_paragraph(text)


def h(text):
    doc.add_heading(text, 1)


def page(title):
    doc.add_page_break()
    h(title)


def table(headers, rows, widths):
    t = doc.add_table(rows=1, cols=len(headers))
    t.autofit = False
    for i, width in enumerate(widths):
        t.columns[i].width = Inches(width)
    for cell, text in zip(t.rows[0].cells, headers):
        cell.text = text
    for row in rows:
        for cell, text in zip(t.add_row().cells, row):
            cell.text = text
    for ri, row in enumerate(t.rows):
        trpr = row._tr.get_or_add_trPr()
        cant = OxmlElement("w:cantSplit")
        trpr.append(cant)
        if ri == 0:
            repeat = OxmlElement("w:tblHeader")
            trpr.append(repeat)
        for ci, cell in enumerate(row.cells):
            cell.width = Inches(widths[ci])
            cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            tcpr = cell._tc.get_or_add_tcPr()
            borders = OxmlElement("w:tcBorders")
            for side in ("top", "left", "bottom", "right"):
                edge = OxmlElement("w:" + side)
                for key, val in (("val", "single"), ("sz", "4"), ("color", "D9D9D9")):
                    edge.set(qn("w:" + key), val)
                borders.append(edge)
            tcpr.append(borders)
            margins = OxmlElement("w:tcMar")
            for side in ("top", "left", "bottom", "right"):
                edge = OxmlElement("w:" + side)
                edge.set(qn("w:w"), "100")
                edge.set(qn("w:type"), "dxa")
                margins.append(edge)
            tcpr.append(margins)
            if ri == 0:
                shade = OxmlElement("w:shd")
                shade.set(qn("w:fill"), "E8E8E8")
                tcpr.append(shade)
            for para in cell.paragraphs:
                para.paragraph_format.space_after = Pt(2)
                para.paragraph_format.line_spacing = 1.05
                for r in para.runs:
                    r.font.size = Pt(10.5)
                    r.bold = ri == 0
    doc.add_paragraph().paragraph_format.space_after = Pt(0)


doc.add_heading("Онтологии в анализе социальных данных с помощью ИИ", 0)
p("Чтобы поручить ИИ анализ сообщений, недостаточно перечислить темы. Нужно определить, какие различия исследователь хочет увидеть и по каким признакам их можно обнаружить. Иначе модель будет подставлять под привычные слова собственные обобщения, а одинаковые названия меток скроют разные способы чтения.")
p("Этот раздел показывает, как описать такие различия, проверить их на примерах и применить к корпусу текстов. Программирование для этого не требуется. Главная работа эксперта состоит в выборе понятий и разборе случаев, где правило не даёт однозначного ответа. Автоматическая разметка затем позволяет искать и считать случаи по принятому правилу; выводы о жизни людей требуют дополнительных оснований.")
h("Начать с вопроса к данным")
p("Предположим, исследователь изучает, как жители обсуждают благоустройство. Его интересует, ограничиваются ли сообщения выражением недовольства, содержат ли просьбу к адресату или приглашают действовать совместно. Для такой задачи положительная и отрицательная тональность слишком грубы: просьба может быть спокойной, а предложение совместного действия — сердитым.")
p("Далее используются только вымышленные сообщения. Они придуманы для объяснения метода и не описывают реальных людей, переписку или результаты исследования.")
table(["Сообщение", "Первое различение"], [
    ("А. «У подъезда опять темно. Вечером возвращаться страшно».", "Недовольство положением дел"),
    ("Б. «Олег, пожалуйста, замените лампу у входа».", "Ожидание действия адресата"),
    ("В. «Соседи, давайте в субботу вместе уберём двор».", "Приглашение действовать совместно"),
    ("Г. «Хорошо бы во дворе стало чище».", "Пожелание без явного приглашения"),
], [4.65, 2.15])
p("До подсчёта сообщений нужно решить, важны ли именно эти различия. Если вопрос касается состояния освещения, понадобится другая схема: объект, вид неисправности, место, время. Одни и те же данные допускают несколько полезных описаний. Смена исследовательского вопроса меняет и то, что следует размечать.")

page("Онтология список меток и граф объектов")
p("В инженерии знаний онтология задаёт понятия предметной области и отношения между ними. Томас Грубер связывает её с явным описанием принятой концептуализации [1]. Для нашей задачи это означает необходимость назвать не только категории сообщений, но и то, какие участники и действия различаются в анализе.")
p("Наталья Ной и Дебора Макгиннесс описывают онтологию через классы, свойства и ограничения; конкретные экземпляры вместе с онтологией образуют базу знаний [2]. Они предлагают начинать с области применения и вопросов, на которые должна отвечать система. Ниже этот подход используется для небольшой схемы анализа сообщений. Она не претендует на исчерпывающее описание общения.")
table(["Представление", "Что оно задаёт", "Пример"], [
    ("Список меток", "Названия возможных ответов", "«Жалоба», «просьба»"),
    ("Онтология", "Смысл понятий и допустимых отношений", "Просьба обращена к участнику и касается ожидаемого действия"),
    ("Граф конкретных объектов", "Экземпляры и связи, извлечённые из данных", "Анна просит Олега заменить лампу в сообщении М17"),
], [1.5, 2.7, 2.6])
p("Список меток удобен для начала, но сам по себе не объясняет, можно ли присвоить сообщению две категории. Например, «Опять темно, Олег, замените лампу» совмещает жалобу и просьбу. Если принудительно выбрать только одну метку, исчезнет существенная для исследования часть сообщения. Возможность сочетать категории должна быть установлена заранее.")
p("Граф отвечает на другой вопрос: кто с кем и как связан в конкретном материале. Пусть вымышленное сообщение М17 гласит: «Анна просит Олега заменить лампу». Здесь можно выделить две сущности типа «участник» и направленную связь «просит». Связь Анна → Олег относится к сообщению М17. Тип этой связи и допустимые типы её концов задаёт онтология, а конкретных участников содержит граф.")
p("К каждой связи нужно сохранить исходный фрагмент. Совместное появление имён ещё не подтверждает просьбу. В сообщении «Анна и Олег обсуждали лампу» связь «просит» не обоснована. Такая привязка позволяет вернуться от таблицы или графа к тексту и проверить, что именно было извлечено.")
p("Небольшая прикладная онтология может быть записана обычным языком в структурированных полях. Полноценные формальные языки и логический вывод нужны не во всех задачах. Важно не называть онтологией любой перечень слов: определения, допустимые связи и границы употребления должны быть доступны для проверки.")

page("Перевести понятия в правила разметки")
p("Определение объясняет смысл понятия, а правило разметки указывает, какое свидетельство искать в данных. Просьба может выражаться косвенно. Нужно установить, какие её проявления учитываются, что исключается и какой контекст необходим.")
table(["Категория", "Включать", "Не считать достаточным"], [
    ("Жалоба", "Есть выраженное недовольство ситуацией или указано причинённое неудобство", "Нейтральное сообщение о факте"),
    ("Просьба", "Обращение предполагает конкретное действие адресата", "Общее пожелание или недовольство без обращения"),
    ("Предложение совместного действия", "Есть приглашение выполнить определённое действие вместе", "Пожелание перемен без приглашения участвовать"),
], [1.5, 2.7, 2.6])
p("Эти формулировки — рабочее решение для нашего вымышленного примера. По ним сообщение А получает метку жалобы, Б — просьбы, В — предложения совместного действия. Для Г ни одна категория не установлена: пожелание чистоты ещё не содержит приглашения действовать. Другой эксперт может предложить более широкое понятие просьбы; тогда спор касается границ понятия, а не только точности модели.")
p("Правило следует проверять на трудном случае. Фраза «Может, уже замените лампу?» может быть просьбой, хотя не содержит слова «пожалуйста». Признаком служит ожидаемое действие адресата, а не вежливая формула. Напротив, слово «прошу» в цитате из чужого письма не доказывает, что автор текущего сообщения сам обращается с просьбой. Для цитирования потребуется отдельное уточнение.")
p("Единицей анализа в этом примере будет сообщение целиком; категория подтверждается фрагментом внутри него. Если взять всю цепочку, просьба одного участника и жалоба другого сольются в одну запись. Подсчёт будет относиться к цепочкам, а не сообщениям. Название показателя должно отражать это различие.")
p("Ответ «Давайте» можно истолковать только с учётом предыдущего предложения. Эксперт решает, передавать ли модели всю ветку или несколько соседних сообщений, и указывает целевую запись. Контекст помогает прочитать эту запись, но не становится дополнительной единицей подсчёта.")
p("Наконец, предусматриваются разные выходы из затруднения. «Не хватает контекста» указывает на недостающие данные. «Не могу определить» сохраняет неопределённость при имеющихся данных. «Ни одна категория» означает осмысленное решение об отсутствии подходящей категории. Эти ответы нельзя объединять в одну отрицательную метку.")

page("Уточнять правила на примерах и ошибках")
p("Проверка начинается с небольшой партии примеров. Для каждого понятия нужны очевидные случаи, внешне похожие отрицательные случаи и пограничные варианты. Модель может их придумать, но такие записи нужно явно помечать как синтетические. Они полезны для обсуждения различий, а не для измерения распространённости явления или качества на реальных сообщениях.")
p("Для предложения совместного действия пара «Давайте вместе уберём двор» и «Хорошо бы во дворе стало чище» проверяет наличие приглашения. Следующая пара может менять только исполнителя: «Давайте уберём двор» и «Попросим службу убрать двор». Такой подбор помогает увидеть, что именно эксперт считает совместным действием. Он не гарантирует, что реальные авторы будут выражаться столь аккуратно.")
p("Эксперт размечает пример до просмотра ответа модели. Иначе предложенная метка может стать незаметной подсказкой. Сначала сохраняются категории, доказательные фрагменты, связи и короткое объяснение решения. Затем открывается предположение модели и разбирается расхождение. Согласие без объяснения на очевидных примерах даёт меньше материала для уточнения правил, чем содержательный спор о границе.")
p("Предположим, модель отнесла сообщение Г к совместному действию. Возможное исправление — прямо исключить пожелания без приглашения участвовать. Но сначала нужно проверить соседний случай: «Если кто-нибудь поможет, в субботу уберу двор». Здесь приглашение выражено условно. Если добавить в правило обязательное слово «давайте», первая ошибка исчезнет ценой нового пропуска. Правка должна касаться смысла условия, а не единственного удобного слова.")
p("Расхождение может иметь несколько причин. Модель могла неверно применить ясное правило; правило могло оставлять два чтения; в записи мог отсутствовать нужный контекст. Иногда эксперт после сопоставления примеров меняет первоначальное определение. Эти случаи требуют разных действий: повторной проверки модели, уточнения правила, добавления контекста или пересмотра самого понятия. Записывать всё как «ошибку ИИ» недостаточно.")
p("В первой версии помощника обучение означает включение утверждённых правил и примеров в запрос к модели. Веса модели не меняются. Модель предлагает исправления, а эксперт принимает или отклоняет их. После правки полезно повторно проверить как вызвавший её пример, так и другие уже разобранные случаи: новое условие может затронуть соседние категории.")
p("В ранних локальных пробах разработки метода изменение формулировки вопроса сопровождалось пересмотром экспертных ответов; проверялось также влияние примеров на применение других правил. Это история поиска процедуры, а не доказательство универсального эффекта. Из неё здесь берётся практическое требование: сохранять версии вопроса и разметки, чтобы не сравнивать ответы на разные задачи как ответы на одну и ту же.")

page("Проверить процедуру на реальных текстах")
p("Успешная разметка придуманных примеров ещё не показывает, как процедура работает на материале исследования. Реальные сообщения содержат сокращения, пропуски, цитаты и неоднозначные обращения. Для проверки нужен набор реальных текстов с экспертной разметкой, относящийся к той области, где будет применяться инструмент.")
p("Гриммер и Стюарт подчёркивают необходимость проверки автоматического анализа в каждом конкретном применении и его зависимость от внимательного чтения [3]. Их статья 2013 года не оценивает сегодняшние большие языковые модели. Здесь используется её методологическое требование проверки, а описанная ниже организация работы предлагается для нашего инструмента.")
p("До настройки реальный материал разделяют на два набора. Первый предназначен для разбора ошибок и уточнения запроса. Второй сохраняется для итоговой проверки уже зафиксированной процедуры. Экспертные ответы второго набора не добавляют в примеры запроса и не используют для предложения новых правил. Если после просмотра этих ошибок правила меняются, прежний набор больше не является независимым подтверждением улучшения.")
p("Разделение проводится по независимым источникам или группам, а не механически по строкам. Копия сообщения, его ответ и соседние реплики одной ветки могут сообщать модели почти одно и то же. Их следует оставить в одном наборе. Для вымышленных сообщений А–Г это означает, что сообщения из одной обсуждаемой цепочки не должны разойтись между настройкой и проверкой. В реальном корпусе связи нужно установить по доступным идентификаторам и проверить дубликаты.")
p("Результат оценивают отдельно по каждой категории. Точность показывает, какая часть присвоенных моделью меток подтверждается эталоном. Полнота показывает, какая часть эталонных положительных случаев найдена. Модель может редко ошибаться, выдавая очень мало меток; высокая точность тогда сочетается с пропусками. Поэтому один общий процент не описывает всех последствий применения процедуры.")
p("Неопределённые ответы и технические ошибки учитываются рядом с этими показателями. Если модель ответила только на лёгкие записи, качество на них нельзя выдавать за качество на всём наборе. Полезно сообщить долю обработанных записей, число отказов и пропущенных эталонных случаев. Для связи «просит» отдельно проверяются тип, направление и участники: правильно найденная категория просьбы не исправляет перепутанные имена.")
p("Эталон одного эксперта задаёт точку сравнения, но не превращает его решение в независимую истину. При важном расхождении можно привлечь второго эксперта и разобрать основания обоих чтений. Порог приемлемости зависит от задачи и последствий ошибок. Для поиска кандидатов на ручное чтение и для публикации частот могут потребоваться разные проверки.")

page("Зафиксировать версию и разметить корпус")
p("Перед массовой разметкой сохраняют версию определений, правил и примеров, а также параметры модели. Запись «использовался ИИ» не позволяет повторить процедуру. Нужны как минимум имя модели, настройки запроса, доступный ей контекст и точный состав примеров. Если внешний сервис изменяет модель под прежним именем, одинаковый запрос не гарантирует прежний результат; это ограничение следует учитывать при повторении исследования.")
p("Изменение смысла правила создаёт новую версию. Например, эксперт решает считать условное приглашение формой совместного действия. Тогда часть ранее отрицательных случаев может стать положительной. Прежняя эталонная разметка не переносится автоматически как проверенная: её нужно пересмотреть относительно нового определения. Иначе сравнение будет наказывать модель за следование уже изменённому правилу.")
p("Корпус размечают зафиксированной процедурой. В каждом результате полезно хранить идентификатор исходной записи, версию онтологии, присвоенные категории, фрагменты и связи. Эти сведения позволяют выбрать все найденные просьбы и проверить их вручную, а также выяснить, каким правилом получена спорная метка. Таблица без такой привязки быстро теряет проверяемость.")
p("Ответ внешнего API сначала проходит техническую проверку. Допустимы ли указанные категории? Существуют ли названные участники связи? Совпадают ли цитаты с переданным текстом? Правильная структура и точная цитата необходимы для пригодного результата, но сами по себе не доказывают верную интерпретацию. Фрагмент может присутствовать в тексте и всё же не подтверждать выбранную категорию.")
p("Сетевой сбой, отказ модели и повреждённый ответ сохраняют как отдельные статусы. Задание можно остановить и продолжить с необработанных записей. Уже сохранённый успешный результат не должен появиться дважды. При обрыве связи нельзя всегда узнать, успел ли провайдер выполнить и тарифицировать запрос; повтор такой записи требует учитывать возможную повторную оплату.")
p("Локальное хранение проекта не означает, что тексты не покидают компьютер. При использовании внешнего API провайдер получает содержание запроса, включая контекст и примеры настройки. Перед запуском нужно проверить получателя, объём и право передавать материалы. Секретный ключ хранят отдельно от базы исследования. В экспорт онтологии по умолчанию включают правила и разрешённые синтетические примеры, а не закрытую переписку.")
p("После завершения просматривают ошибки и спорные случаи, проверяют выборку обычных ответов и выгружают результаты. В вымышленном примере можно посчитать сообщения с просьбами, найти сочетания просьбы и жалобы, построить связи между названными участниками. Любая такая таблица описывает корпус в пределах выбранной единицы анализа и версии правил.")

page("От разметки текста к выводу о социальной реальности")
p("Утверждение «в корпусе стало больше сообщений с меткой жалобы» ещё не означает, что жители стали более недовольны. Мог измениться состав авторов, способ отбора сообщений или площадка обсуждения. Один человек мог отправить несколько похожих записей. Даже безошибочная разметка не устраняет эти различия, потому что они относятся к происхождению данных и единице наблюдения.")
p("Предложение совместного действия также не доказывает, что действие состоялось. Сообщение В позволяет исследовать приглашение к уборке, но не участие в ней. Для вывода о состоявшемся событии потребуются другие свидетельства: последующие сообщения, наблюдение или иной обоснованный источник. Отсутствие приглашения в собранных текстах не доказывает отсутствия договорённостей вне этой переписки.")
p("Таким образом, нужно раздельно обосновать два перехода: от исходного текста к присвоенной категории и от распределения категорий к содержательному выводу. Первый проверяется правилами, фрагментами и сопоставлением с экспертной разметкой. Второй требует объяснить выборку, охват наблюдений и связь текстового признака с исследуемым явлением. Онтология делает первый переход более явным, но не выполняет второй за исследователя.")
p("Практическое упражнение. Возьмите сообщение Г и придумайте два минимальных изменения: одно должно превратить пожелание в просьбу, другое — в предложение совместного действия. Для каждого варианта укажите решающий фрагмент. Затем придумайте случай, где выбранного правила недостаточно без контекста. Если ответы вызывают спор, сначала уточните границу понятия, а не ищите модель, которая чаще согласится с первым решением.")
h("Литература")
